"""Files API — STS-credentialed S3 uploads.

Fetches short-lived AWS credentials from ``POST /storage/credentials``
and uses ``boto3`` to upload files (with native multipart for large
artifacts). The server picks the backing bucket (managed / releases /
matching Storage Integration) from the destination ``s3://`` path the
SDK sends, so callers only need to know where they want the file to
land — no AWS credentials need to ever leave the user's environment.

Security posture: credentials never appear in repr/str/pickle (see
``TemporaryAwsCredentials``). The SDK's own log statements only emit
file paths and high-level status, never credential material.
"""

from __future__ import annotations

import contextlib
import os
import tempfile
import uuid
from pathlib import Path
from typing import Any, Literal
from urllib.parse import urlparse

import boto3
import requests
from botocore.credentials import RefreshableCredentials
from botocore.session import Session as BotocoreSession

from wherobots.api.base import BaseClient
from wherobots.config import WherobotsConfig
from wherobots.exceptions import WherobotsAPIError, WherobotsValidationError
from wherobots.models import StorageIntegration, TemporaryAwsCredentials
from wherobots.utils.logger import get_logger

logger = get_logger("api.files")


class FilesAPI:
    """Upload files to Wherobots-managed storage and Storage Integrations.

    Each upload session fetches short-lived AWS STS credentials scoped
    to a specific ``s3://`` destination path via
    ``POST /storage/credentials``. The credentials are wrapped in
    ``botocore.credentials.RefreshableCredentials`` so multi-hour
    multipart uploads survive the standard 1-hour STS lifetime.

    Args:
        client: A configured ``BaseClient`` instance.
    """

    def __init__(self, client: BaseClient) -> None:
        self._client = client
        self._integrations_cache: list[StorageIntegration] | None = None

    # ------------------------------------------------------------------ #
    # Factory
    # ------------------------------------------------------------------ #

    @classmethod
    def from_config(cls, config: WherobotsConfig, **kwargs: Any) -> FilesAPI:
        """Build a ``FilesAPI`` from a ``WherobotsConfig``.

        Args:
            config: Validated configuration object.
            **kwargs: Additional keyword arguments forwarded to
                ``BaseClient.__init__`` (e.g. ``max_retries``).

        Returns:
            A new ``FilesAPI`` instance backed by the configured client.
        """
        client = BaseClient(config, **kwargs)
        return cls(client)

    # ------------------------------------------------------------------ #
    # Credential & storage endpoints
    # ------------------------------------------------------------------ #

    def get_storage_credentials(
        self,
        path: str,
        access_mode: Literal["read", "read_write"] = "read",
    ) -> TemporaryAwsCredentials:
        """Fetch temporary AWS STS credentials scoped to *path*.

        Calls ``POST /storage/credentials``. The server resolves the
        path against managed storage, the WherobotsDB releases bucket,
        and any matching Storage Integration in that order.

        Args:
            path: ``s3://bucket/prefix`` URI to obtain credentials for.
            access_mode: ``"read"`` (default — least privilege) or
                ``"read_write"`` to also allow ``s3:PutObject``. The
                SDK's upload paths pass ``"read_write"`` explicitly;
                callers using this method directly should leave the
                default unless they specifically need write access.

        Returns:
            A ``TemporaryAwsCredentials`` object — secrets are masked
            in ``repr``.

        Raises:
            WherobotsAPIError: On HTTP or JSON-parsing failures. The
                error message and attached payload are **scrubbed** —
                neither will reference any credential field even if the
                server replied with a partially-populated body.
        """
        try:
            response = self._client.post(
                "/storage/credentials",
                json_body={"path": path, "access_mode": access_mode},
            )
        except WherobotsAPIError as exc:
            # Scrub: never let the credentials endpoint's error
            # response body bubble out — it could contain partial
            # credential fields in pathological server-bug scenarios.
            raise WherobotsAPIError(
                f"Credential request failed (status {exc.status_code})",
                status_code=exc.status_code,
                request_id=exc.request_id,
            ) from None
        try:
            data = response.json()
        except (ValueError, requests.exceptions.JSONDecodeError) as exc:
            raise WherobotsAPIError(
                f"Invalid JSON in /storage/credentials response (status {response.status_code})",
                status_code=response.status_code,
            ) from exc
        try:
            return TemporaryAwsCredentials.from_dict(data)
        except ValueError as exc:
            # ValueError from from_dict references field NAMES only —
            # safe to surface — but re-raise as WherobotsAPIError for
            # callers that catch the SDK's exception hierarchy.
            raise WherobotsAPIError(
                f"Credential response is invalid: {exc}",
                status_code=response.status_code,
            ) from None

    def list_integrations(self, *, refresh: bool = False) -> list[StorageIntegration]:
        """List all storage sources (``GET /storage``).

        Includes the org's managed source (``type == "MANAGED"``) and
        any user-configured integration sources (``type == "INTEGRATION"``).

        Args:
            refresh: Force a fresh fetch even if the instance has cached
                results.

        Returns:
            A list of ``StorageIntegration`` objects.

        Raises:
            WherobotsAPIError: On HTTP or JSON-parsing failures.
        """
        if not refresh and self._integrations_cache is not None:
            return self._integrations_cache
        response = self._client.get("/storage")
        try:
            data = response.json()
        except (ValueError, requests.exceptions.JSONDecodeError) as exc:
            raise WherobotsAPIError(
                f"Invalid JSON in /storage response (status {response.status_code})",
                status_code=response.status_code,
            ) from exc
        items = [StorageIntegration.from_dict(item) for item in data]
        self._integrations_cache = items
        return items

    def resolve_integration(
        self,
        name_or_id: str,
        *,
        refresh: bool = False,
    ) -> StorageIntegration:
        """Find a storage integration by name (case-insensitive) or ID.

        Args:
            name_or_id: The integration name or unique ID.
            refresh: Force a fresh fetch of integrations.

        Returns:
            The matching ``StorageIntegration``.

        Raises:
            WherobotsValidationError: If no matching integration is found.
            WherobotsAPIError: On HTTP failures.
        """
        integrations = self.list_integrations(refresh=refresh)
        query = name_or_id.lower()
        for integration in integrations:
            if integration.id == name_or_id or integration.name.lower() == query:
                return integration
        available = [i.name for i in integrations if not i.is_managed]
        raise WherobotsValidationError(
            f"Storage integration '{name_or_id}' not found. Available integrations: {available}"
        )

    def get_managed_storage(self, *, refresh: bool = False) -> StorageIntegration:
        """Return the org's managed storage source.

        Looks for the entry in ``GET /storage`` with ``type == "MANAGED"``.
        Cached on the instance after the first call.

        Args:
            refresh: Force a fresh fetch.

        Returns:
            The managed ``StorageIntegration``.

        Raises:
            WherobotsValidationError: If no managed source is configured.
            WherobotsAPIError: On HTTP failures.
        """
        integrations = self.list_integrations(refresh=refresh)
        for integration in integrations:
            if integration.is_managed:
                return integration
        raise WherobotsValidationError(
            "No managed storage source found in /storage. "
            "The organization may not have managed storage provisioned."
        )

    # ------------------------------------------------------------------ #
    # Upload primitives
    # ------------------------------------------------------------------ #

    def upload_file(self, local_path: str, dest_uri: str) -> str:
        """Upload a local file to an explicit ``s3://`` destination.

        Fetches read_write credentials scoped to *dest_uri*, then runs a
        boto3 multipart upload. Streams from disk — large files are not
        loaded fully into memory. Credentials are wrapped in a
        ``RefreshableCredentials`` so uploads exceeding the 1h STS
        lifetime keep working.

        Args:
            local_path: Filesystem path to the file to upload.
            dest_uri: Destination ``s3://bucket/key`` URI. The server
                picks the backing bucket from this path.

        Returns:
            *dest_uri* on success.

        Raises:
            WherobotsValidationError: If the local file doesn't exist
                or the URI is malformed.
            WherobotsAPIError: On credential fetch failure.
        """
        path = Path(local_path)
        if not path.is_file():
            raise WherobotsValidationError(f"File not found: {local_path}")

        try:
            file_size = path.stat().st_size
        except OSError as exc:
            raise WherobotsValidationError(f"Cannot read file '{local_path}': {exc}") from exc

        bucket, key = _parse_s3_uri(dest_uri)
        if not key:
            raise WherobotsValidationError(f"Destination URI must include a key (got '{dest_uri}')")

        logger.info("Uploading '%s' (%d bytes) to %s", path.name, file_size, dest_uri)
        s3, initial = self._build_s3_client(dest_uri)
        try:
            s3.upload_file(Filename=str(path), Bucket=bucket, Key=key)
        finally:
            # Best-effort local eviction: zero our handle on the
            # initial creds. The ``RefreshableCredentials`` instance
            # inside botocore holds its own copy of the same secret
            # material — it goes out of scope (and becomes eligible
            # for GC) when ``s3`` is dropped at function return.
            # AWS-side revocation is not possible via the SDK; rely
            # on the short STS TTL for ultimate invalidation.
            initial.wipe()
            del s3
        logger.info("Upload complete: %s", dest_uri)
        return dest_uri

    def upload_managed_file(
        self,
        local_path: str,
        subdir: str,
        dest_filename: str | None = None,
    ) -> str:
        """Upload to managed storage under ``{managed.path}/{subdir}/{name}``.

        Args:
            local_path: Local file to upload.
            subdir: Subdirectory under the managed source's path
                (e.g. ``"scripts"``, ``"dependencies"``).
            dest_filename: Optional destination filename. Defaults to
                ``Path(local_path).name``.

        Returns:
            The ``s3://`` URI of the uploaded file.

        Raises:
            WherobotsValidationError: If the file path or filename are
                invalid, or no managed storage is configured.
            WherobotsAPIError: On credential or upload failures.
        """
        filename = dest_filename or Path(local_path).name
        _validate_filename(filename)
        source = self.get_managed_storage()
        dest_uri = self._dest_uri_for(source, filename, subdir)
        return self.upload_file(local_path, dest_uri)

    def upload_script(
        self,
        content: str | bytes,
        filename: str | None = None,
    ) -> str:
        """Upload script content (string or bytes) to managed storage.

        Writes *content* to a temporary file, then delegates to
        :meth:`upload_managed_file` under the ``scripts/`` subdir. For
        an already-on-disk file, prefer :meth:`upload_managed_file`
        directly to avoid the temp-file roundtrip.

        Args:
            content: Script source (string) or raw bytes.
            filename: Optional destination filename. Defaults to a
                UUID-based name (``sdk-upload-{uuid}.py``).

        Returns:
            The ``s3://`` URI of the uploaded script.

        Raises:
            WherobotsValidationError: If the filename is invalid.
            WherobotsAPIError: On credential or upload failures.
        """
        if filename is None:
            filename = f"sdk-upload-{uuid.uuid4().hex[:12]}.py"
        _validate_filename(filename)

        data = content.encode("utf-8") if isinstance(content, str) else content
        # Use delete=False so boto3 can re-open the path by name (Windows
        # forbids a second handle while delete=True is open). We unlink
        # explicitly in finally — succeed or fail, the temp file goes away.
        fd, tmp_path = tempfile.mkstemp(suffix=Path(filename).suffix)
        try:
            with os.fdopen(fd, "wb") as tmp:
                tmp.write(data)
            return self.upload_managed_file(tmp_path, "scripts", dest_filename=filename)
        finally:
            with contextlib.suppress(OSError):
                os.unlink(tmp_path)

    def upload_dependency(
        self,
        local_path: str,
        *,
        storage_integration: str | None = None,
        dest_filename: str | None = None,
        dest_subdir: str | None = None,
    ) -> str:
        """Upload a dependency file (wheel, jar, zip, json).

        Destination rules differ by scope (intentional — the integration
        owner controls their bucket structure):

        - **Managed** (``storage_integration=None``): file lands under
          ``{managed.path}/dependencies/{filename}`` unless
          ``dest_subdir`` is set, in which case ``dest_subdir`` replaces
          the default ``dependencies/`` segment.
        - **Storage Integration**: file lands at
          ``{integration.path}/{default_directory}/{dest_subdir}/{filename}``
          (skipping any empty segment). There is **no implicit**
          ``dependencies/`` for integrations — if the integration has
          no ``default_directory`` and no ``dest_subdir`` is supplied,
          the file lands at the integration root. Use ``dest_subdir``
          to organize artifacts inside the integration.

        Args:
            local_path: Local file path to upload.
            storage_integration: Optional integration name or ID. When
                ``None``, the file is uploaded to managed storage.
            dest_filename: Optional destination filename. Defaults to
                ``Path(local_path).name``.
            dest_subdir: Optional subdirectory under the destination
                source's root. See destination rules above. Each
                segment is validated against :func:`_validate_filename`
                so traversal is rejected.

        Returns:
            The ``s3://`` URI of the uploaded dependency.

        Raises:
            WherobotsValidationError: If the file path, filename, or
                subdir are invalid, or the storage integration is
                unknown.
            WherobotsAPIError: On credential or upload failures.
        """
        filename = dest_filename or Path(local_path).name
        _validate_filename(filename)
        subdir = _normalize_subdir(dest_subdir)

        if storage_integration is None:
            return self.upload_managed_file(
                local_path,
                subdir if subdir else "dependencies",
                dest_filename=filename,
            )

        source = self.resolve_integration(storage_integration)
        dest_uri = self._dest_uri_for(source, filename, subdir)
        return self.upload_file(local_path, dest_uri)

    # ------------------------------------------------------------------ #
    # Path helpers
    # ------------------------------------------------------------------ #

    def dest_uri_for(
        self,
        source: StorageIntegration,
        filename: str,
        subdir: str | None = None,
    ) -> str:
        """Build an ``s3://`` destination URI under *source*'s root.

        Honors *source*'s ``default_directory`` if set, then the
        optional *subdir*, then *filename*. Use the resulting URI with
        :meth:`upload_file` when you want explicit, predictable
        destinations (e.g. for a job script you intend to reference
        as ``WherobotsJob(script=<uri>)``).

        Args:
            source: A ``StorageIntegration`` returned from
                :meth:`list_integrations`, :meth:`resolve_integration`,
                or :meth:`get_managed_storage`.
            filename: Bare filename (no slashes).
            subdir: Optional path segment(s) between the source root
                and the filename. Validated against the same
                traversal rules as filenames.

        Returns:
            ``s3://<bucket>/<...>/<filename>``.

        Raises:
            WherobotsValidationError: On filename / subdir traversal.
        """
        _validate_filename(filename)
        return self._dest_uri_for(source, filename, _normalize_subdir(subdir))

    # ------------------------------------------------------------------ #
    # Internals
    # ------------------------------------------------------------------ #

    def _dest_uri_for(
        self,
        source: StorageIntegration,
        filename: str,
        subdir: str,
    ) -> str:
        """Build an s3:// URI under *source*'s prefix.

        Honors ``source.default_directory`` if present, then *subdir*,
        then *filename*. Trailing slashes in the source path are
        normalized.
        """
        base = source.path.rstrip("/")
        parts: list[str] = [base]
        if source.default_directory:
            parts.append(source.default_directory.strip("/"))
        if subdir:
            parts.append(subdir.strip("/"))
        parts.append(filename)
        return "/".join(p for p in parts if p)

    def _refresh_credentials_for(self, dest_uri: str) -> dict[str, str]:
        """Botocore-shaped refresh callback for *dest_uri*.

        Public-internal: exposed for unit testing without reaching into
        botocore internals. Each invocation re-hits
        ``POST /storage/credentials`` and returns the credential dict
        botocore expects. The intermediate
        :class:`TemporaryAwsCredentials` handle is wiped before
        returning so our reference doesn't outlive the call.
        """
        fresh = self.get_storage_credentials(dest_uri, access_mode="read_write")
        payload = {
            "access_key": fresh.access_key_id,
            "secret_key": fresh.secret_access_key,
            "token": fresh.session_token,
            "expiry_time": fresh.expiration.isoformat(),
        }
        fresh.wipe()
        return payload

    def _build_s3_client(self, dest_uri: str) -> tuple[Any, TemporaryAwsCredentials]:
        """Build a boto3 S3 client with refreshable creds scoped to *dest_uri*.

        Returns ``(client, initial_credentials)`` so the caller can
        :meth:`~TemporaryAwsCredentials.wipe` the initial credentials
        once the upload finishes. The refresh callback re-hits
        ``/storage/credentials`` whenever botocore decides the cached
        creds are within the mandatory refresh window — this keeps
        long multipart uploads alive across the 1h STS lifetime, and
        wipes the returned-from-refresh ``TemporaryAwsCredentials``
        before handing the raw values to botocore so our reference
        does not outlive the call.
        """
        initial = self.get_storage_credentials(dest_uri, access_mode="read_write")
        creds = RefreshableCredentials.create_from_metadata(
            metadata={
                "access_key": initial.access_key_id,
                "secret_key": initial.secret_access_key,
                "token": initial.session_token,
                "expiry_time": initial.expiration.isoformat(),
            },
            refresh_using=lambda: self._refresh_credentials_for(dest_uri),
            method="wherobots-storage-credentials",
        )
        botocore_session = BotocoreSession()
        botocore_session._credentials = creds
        client = boto3.Session(botocore_session=botocore_session).client(
            "s3", region_name=initial.region
        )
        return client, initial

    # ------------------------------------------------------------------ #
    # Lifecycle
    # ------------------------------------------------------------------ #

    def close(self) -> None:
        """Close the underlying HTTP client and release resources."""
        self._client.close()

    def __enter__(self) -> FilesAPI:
        """Enter the runtime context (context-manager protocol)."""
        return self

    def __exit__(self, *exc: Any) -> None:
        """Exit the runtime context, closing the client."""
        self.close()


# ---------------------------------------------------------------------------
# Module-level helpers
# ---------------------------------------------------------------------------


def _parse_s3_uri(uri: str) -> tuple[str, str]:
    """Split an ``s3://bucket/key`` URI into (bucket, key).

    Raises:
        WherobotsValidationError: If the URI scheme is not ``s3``.
    """
    parsed = urlparse(uri)
    if parsed.scheme != "s3" or not parsed.netloc:
        raise WherobotsValidationError(f"Expected s3:// URI, got '{uri}'")
    return parsed.netloc, parsed.path.lstrip("/")


def _validate_filename(filename: str) -> None:
    """Reject path-traversal characters in user-supplied filenames."""
    if not filename:
        raise WherobotsValidationError("filename must not be empty")
    if "/" in filename or "\\" in filename or ".." in filename:
        raise WherobotsValidationError(
            f"Invalid filename '{filename}': must not contain '/', '\\', or '..'"
        )


def _normalize_subdir(subdir: str | None) -> str:
    """Normalize and validate a user-supplied multi-segment subdir.

    Returns the normalized form (``"a/b/c"``) or ``""`` for None/empty.
    Each segment is run through :func:`_validate_filename` so traversal
    (``..``, ``\\``) is rejected. Leading/trailing slashes and empty
    segments are stripped.
    """
    if not subdir:
        return ""
    segments = [seg for seg in subdir.replace("\\", "/").split("/") if seg]
    for seg in segments:
        _validate_filename(seg)
    return "/".join(segments)
